      faqTitle: 'Usein kysytyt kysymykset',
      faq1Q: 'Miten saan lippuni oston jälkeen?',
      faq1A: 'Kun maksusi on vahvistettu, digitaalinen lippusi ainutlaatuisella QR-koodilla on heti saatavilla käyttäjäprofiilisi "Omat liput" -osiossa. Saat myös vahvistusviestin sähköpostitse linkillä lipputasi.',
      faq2Q: 'Mikä on tapahtumien palautuskäytäntö?',
      faq2A: 'Palautuskäytännöt asettavat yksittäiset järjestäjät. Yleensä voit pyytää täyttä palautusta enintään 24 tuntia ennen tapahtuman alkua. Tarkista tietyt ehdot tapahtuman tietojen sivulta.',
      faq3Q: 'Miten luon yksityisen, vain kutsulla tapahtuvan?',
      faq3A: 'Tapahtuman luomisen aikana (Vaihe 3) valitse "Yksityinen / Vain kutsuilla". Tämä piilottaa tapahtumasi kartalta. Voit sitten jakaa salaisen linkin tai pääsykoodin vieraillesi.',
      faq4Q: 'Miten AI-käännös toimii?',
      faq4A: 'EventNexus käyttää Gemini AI:ta automaattisesti kääntääkseen tapahtumasi nimen ja kuvauksen yli 12 kielelle. Tämä tapahtuu automaattisesti julkaisun yhteydessä, varmistaen globaalin kattavuuden ilman lisätyötä.',
      faq5Q: 'Miksi ensimmäisellä maksullani on odotusaika?',
      faq5A: 'Stripe vaatii pakollisen 7-14 päivän odotusajan ensimmäiselle maksullesi osana heidän riskinhallintaprosessiaan. Tätä ei voida poistaa missään olosuhteissa. Kaikki muutokset maksutapaan tai aikatauluun tänä aikana tulevat voimaan odotusajan päätyttyä. Voit tarkistaa arvioitu maksupäiväsi Stripe Dashboard -sivustolta.',
      faq6Q: 'Milloin saan maksuni tapahtuman jälkeen?',
      faq6A: 'Maksut käsitellään automaattisesti 2 päivää tapahtumasi päättymisen jälkeen. Tämä antaa aikaa palautuspyynnöille ja varmistaa turvalliset transaktiot. Ensimmäinen maksusi sisältää 7-14 päivän Stripen odotusajan. Sen jälkeen seuraavat maksut noudattavat tavallista 2 päivän aikataulua Supabasesta.',
      contactTitle: 'Tarvitsetko vielä apua?',
