    terms: {
      title: 'Nutzungsbedingungen',
      lastUpdated: '20. Januar 2026',
      section1Title: '1. Annahme der Bedingungen',
      section1Content: 'Durch den Zugriff auf oder die Nutzung von EventNexus erklären Sie sich mit diesen Nutzungsbedingungen einverstanden. Wenn Sie nicht mit allen Bedingungen einverstanden sind, dürfen Sie die Plattform nicht nutzen. Wir behalten uns das Recht vor, diese Bedingungen jederzeit zu aktualisieren.',
      section2Title: '2. Benutzerkonten',
      section2Content: 'Sie müssen mindestens 18 Jahre alt sein, um ein Konto zu erstellen. Sie sind für die Sicherheit Ihres Kontos und Passworts verantwortlich. EventNexus haftet nicht für Verluste oder Schäden, die durch Ihre Nichteinhaltung dieser Sicherheitsverpflichtung entstehen.',
      section3Title: '3. Ticketkäufe und Rückerstattungen',
      section3Content: 'Alle Ticketkäufe sind endgültig, vorbehaltlich der vom Veranstalter festgelegten Rückerstattungsrichtlinie. EventNexus tritt als Vermittler auf; wir sind nicht für Veranstaltungsabsagen verantwortlich, erleichtern jedoch Rückerstattungen, wenn dies vom Veranstalter genehmigt wird.',
      section4Title: '4. Inhalte und Verhalten',
      section4Content: 'Sie dürfen die Plattform nicht für illegale oder unbefugte Zwecke nutzen. Sie sind allein verantwortlich für die von Ihnen hochgeladenen Inhalte, einschließlich Veranstaltungsbeschreibungen, Bilder und Bewertungen. Wir behalten uns das Recht vor, Inhalte zu entfernen, die gegen unsere Community-Standards verstoßen.',
    },
    privacy: {
      title: 'Datenschutzrichtlinie',
      lastUpdated: '20. Januar 2026',
      section1Title: '1. Einführung',
      section1Content: 'Bei EventNexus priorisieren wir die Sicherheit Ihrer Daten. Diese Datenschutzrichtlinie erklärt, wie wir Ihre persönlichen Daten sammeln, verwenden und schützen. Wir sind der Transparenz und DSGVO-Compliance für alle unsere Benutzer verpflichtet, insbesondere in der Europäischen Union.',
      section2Title: '2. Datenerfassung',
      section2Content: 'Wir sammeln minimale Daten, um personalisierte Veranstaltungsempfehlungen über unsere KI-Engine bereitzustellen. Die gesammelten Informationen umfassen: E-Mail-Adresse (erforderlich für Kontoerstellung und Veranstaltungsupdates), Name und Profilinformationen (optional), Standortdaten über GPS für kartenbasierte Entdeckung (mit Ihrer Erlaubnis), Nutzungsstatistiken und Geräteinformationen (automatisch gesammelt) und Zahlungsinformationen, die sicher über Stripe verarbeitet werden (wir speichern Ihre Kreditkarteninformationen nicht).',
      section3Title: '3. Wie wir Daten verwenden',
      section3Content: 'Ihre Daten werden verwendet für: Bereitstellung des kartenbasierten Entdeckungsdienstes und personalisierter Veranstaltungsempfehlungen, unterstützt durch unsere KI-Engine (Google Gemini), sichere Verarbeitung von Tickettransaktionen über Stripe, Senden von Veranstaltungsupdates und Benachrichtigungen über Veranstaltungen, die Sie interessieren, Verbesserung der Plattformleistung durch Analysen und KI-gestützte Erkenntnisse sowie Gewährleistung der Sicherheit und Betrugsprävention.',
      section4Title: '4. Datenweitergabe',
      section4Content: 'Wir geben Ihre Kontaktinformationen nur an Veranstalter für Veranstaltungen weiter, für die Sie Tickets gekauft haben. Wir verkaufen Ihre persönlichen Daten nicht an Dritte für Marketingzwecke. Wir nutzen vertrauenswürdige Dienstleister: Google Cloud Infrastructure (Hosting und KI-Dienste), Stripe (Zahlungsabwicklung) und Supabase (sichere Datenbank mit PostgreSQL). Alle Dienstleister sind vertraglich verpflichtet, Ihre Daten zu schützen und DSGVO-Standards einzuhalten.',
      section5Title: '5. Infrastruktur und Sicherheit',
      section5Content: 'EventNexus nutzt Google Cloud Infrastructure für das Hosting unserer Dienste und gewährleistet Sicherheit und Zuverlässigkeit auf Unternehmensniveau. Alle Daten sind während der Übertragung und im Ruhezustand verschlüsselt. Wir implementieren robuste Sicherheitsprotokolle, einschließlich Row Level Security (RLS)-Richtlinien in unserer Datenbank, PCI DSS Level 1-konforme Zahlungsabwicklung über Stripe sowie regelmäßige Sicherheitsaudits und Überwachung. Wir sind vollständig DSGVO-konform zum Schutz unserer EU-Benutzer.',
      section6Title: '6. Ihre Rechte (DSGVO)',
      section6Content: 'Gemäß DSGVO haben Sie das Recht: auf Zugang zu Ihren persönlichen Daten, Korrektur ungenauer Daten, Löschung Ihrer Daten (Recht auf Vergessenwerden), Widerspruch gegen Datenverarbeitung, Datenübertragbarkeit und jederzeitiger Widerruf der Einwilligung. Um diese Rechte auszuüben, kontaktieren Sie uns unter support@eventnexus.eu, Antwortzeit innerhalb von 24 Stunden.',
      section7Title: '7. Datenspeicherung',
      section7Content: 'Wir bewahren Ihre persönlichen Daten nur so lange auf, wie es zur Erbringung unserer Dienstleistungen und zur Erfüllung gesetzlicher Verpflichtungen erforderlich ist. Kontodaten werden aufbewahrt, solange Ihr Konto aktiv ist. Transaktionsaufzeichnungen werden 7 Jahre lang für steuerliche und rechtliche Compliance aufbewahrt. Marketingkommunikationsdaten werden aufbewahrt, bis Sie sich abmelden.',
      section8Title: '8. Cookies und Tracking',
      section8Content: 'Wir verwenden wesentliche Cookies für Authentifizierung und Sitzungsverwaltung. Analyse-Cookies helfen uns zu verstehen, wie Sie unsere Plattform nutzen (Sie können sich abmelden). Wir verwenden keine Werbe-Cookies von Drittanbietern. Sie können Cookie-Einstellungen in Ihren Browsereinstellungen verwalten.',
      section9Title: '9. Internationale Datenübertragungen',
      section9Content: 'Ihre Daten können in Ländern außerhalb der EU verarbeitet werden, einschließlich der Vereinigten Staaten (Google Cloud, Stripe). Wir gewährleisten angemessenen Schutz durch: von der Europäischen Kommission genehmigte Standardvertragsklauseln (SCCs) und nach dem EU-US Data Privacy Framework zertifizierte Dienstleister, wo zutreffend.',
      section10Title: '10. Datenschutz für Kinder',
      section10Content: 'EventNexus ist nicht für Benutzer unter 16 Jahren bestimmt. Wir sammeln wissentlich keine Daten von Kindern. Wenn Sie glauben, dass wir Daten von einem Kind gesammelt haben, kontaktieren Sie uns sofort.',
      section11Title: '11. Änderungen dieser Richtlinie',
      section11Content: 'Wir können diese Datenschutzrichtlinie von Zeit zu Zeit aktualisieren. Wir werden Sie über wesentliche Änderungen per E-Mail oder durch auffällige Mitteilung auf unserer Plattform informieren. Die fortgesetzte Nutzung nach Änderungen bedeutet Akzeptanz.',
      section12Title: '12. Kontaktieren Sie uns',
      section12Content: 'Für datenschutzbezogene Fragen oder zur Ausübung Ihrer Rechte kontaktieren Sie uns unter: E-Mail: support@eventnexus.eu, Antwortzeit: Innerhalb von 24 Stunden, Adresse: Põltsamaa, Estland, Rechtsträger: EventNexus OÜ',
    },
