      faqTitle: 'Häufig gestellte Fragen',
      faq1Q: 'Wie erhalte ich mein Ticket nach dem Kauf?',
      faq1A: 'Sobald Ihre Zahlung bestätigt ist, steht Ihr digitales Ticket mit einem eindeutigen QR-Code sofort in Ihrem Benutzerprofil unter "Meine Tickets" zur Verfügung. Sie erhalten auch eine Bestätigungs-E-Mail mit einem Link zu Ihrem Ticket.',
      faq2Q: 'Was ist die Rückerstattungsrichtlinie für Veranstaltungen?',
      faq2A: 'Rückerstattungsrichtlinien werden von einzelnen Veranstaltern festgelegt. Im Allgemeinen können Sie bis 24 Stunden vor Veranstaltungsbeginn eine vollständige Rückerstattung beantragen. Überprüfen Sie die Veranstaltungsdetailseite für spezifische Bedingungen.',
      faq3Q: 'Wie erstelle ich eine private, nur auf Einladung zugängliche Veranstaltung?',
      faq3A: 'Wählen Sie während des Veranstaltungserstellungsflusses (Schritt 3) "Privat / Nur auf Einladung". Dies verbirgt Ihre Veranstaltung von der Karte. Sie können dann einen geheimen Link oder Zugangscode mit Ihren Gästen teilen.',
      faq4Q: 'Wie funktioniert die KI-Übersetzung?',
      faq4A: 'EventNexus verwendet Gemini KI, um Ihren Veranstaltungsnamen und Ihre Beschreibung automatisch in über 12 Sprachen zu übersetzen. Dies geschieht automatisch bei der Veröffentlichung und gewährleistet globale Reichweite ohne zusätzliche Arbeit.',
      faq5Q: 'Warum hat meine erste Auszahlung eine Wartezeit?',
      faq5A: 'Stripe erfordert eine obligatorische Wartezeit von 7-14 Tagen für Ihre erste Auszahlung als Teil ihres Risikominderungsprozesses. Dies kann unter keinen Umständen aufgehoben werden. Alle Änderungen an Ihrer Auszahlungsmethode oder Ihrem Zeitplan während dieser Zeit werden nach Ende der Wartezeit wirksam. Sie können Ihr voraussichtliches Auszahlungsdatum in Ihrem Stripe-Dashboard überprüfen.',
      faq6Q: 'Wann erhalte ich meine Auszahlung nach einer Veranstaltung?',
      faq6A: 'Auszahlungen werden automatisch 2 Tage nach Abschluss Ihrer Veranstaltung verarbeitet. Dies ermöglicht Zeit für Rückerstattungsanfragen und gewährleistet sichere Transaktionen. Ihre erste Auszahlung beinhaltet die 7-14-tägige Stripe-Wartezeit. Danach folgen nachfolgende Auszahlungen dem standardmäßigen 2-Tage-Zeitplan von Supabase.',
