      faqTitle: 'Vanliga frågor',
      faq1Q: 'Hur får jag min biljett efter köp?',
      faq1A: 'När din betalning är bekräftad blir din digitala biljett med en unik QR-kod omedelbart tillgänglig i din användarprofil under "Mina biljetter". Du får också ett bekräftelsemejl med en länk till din biljett.',
      faq2Q: 'Vad är återbetalningspolicyn för evenemang?',
      faq2A: 'Återbetalningspolicyer fastställs av enskilda arrangörer. I allmänhet kan du begära full återbetalning upp till 24 timmar före evenemangets start. Kontrollera evenemangsdetaljsidan för specifika villkor.',
      faq3Q: 'Hur skapar jag ett privat, endast inbjudningsevenemang?',
      faq3A: 'Under evenemangsskapandeflödet (Steg 3), välj "Privat / Endast inbjudan". Detta döljer ditt evenemang från kartan. Du kan sedan dela en hemlig länk eller åtkomstkod med dina gäster.',
      faq4Q: 'Hur fungerar AI-översättning?',
      faq4A: 'EventNexus använder Gemini AI för att automatiskt översätta ditt evenemangsnamn och beskrivning till över 12 språk. Detta händer automatiskt vid publicering och säkerställer global räckvidd utan extra arbete.',
      faq5Q: 'Varför har min första utbetalning en väntetid?',
      faq5A: 'Stripe kräver en obligatorisk vänteperiod på 7-14 dagar för din första utbetalning som en del av deras riskminskningsprocess. Detta kan inte åsidosättas under några omständigheter. Eventuella ändringar av din utbetalningsmetod eller schema under denna tid träder i kraft efter att vänteperioden slutar. Du kan kontrollera ditt beräknade utbetalningsdatum i din Stripe-instrumentpanel.',
      faq6Q: 'När får jag min utbetalning efter ett evenemang?',
      faq6A: 'Utbetalningar behandlas automatiskt 2 dagar efter att ditt evenemang slutförs. Detta tillåter tid för återbetalningsförfrågningar och säkerställer säkra transaktioner. Din första utbetalning inkluderar 7-14 dagars Stripe vänteperiod. Därefter följer efterföljande utbetalningar Supabases standardschema på 2 dagar.',
