    terms: {
      title: 'Conditions d\'utilisation',
      lastUpdated: '20 janvier 2026',
      section1Title: '1. Acceptation des conditions',
      section1Content: 'En accédant à ou en utilisant EventNexus, vous acceptez ces conditions d\'utilisation. Si vous n\'acceptez pas toutes les conditions, vous ne pouvez pas utiliser la plateforme. Nous nous réservons le droit de mettre à jour ces conditions à tout moment.',
      section2Title: '2. Comptes utilisateurs',
      section2Content: 'Vous devez avoir au moins 18 ans pour créer un compte. Vous êtes responsable de la sécurité de votre compte et de votre mot de passe. EventNexus n\'est pas responsable des pertes ou dommages résultant de votre non-respect de cette obligation de sécurité.',
      section3Title: '3. Achats de billets et remboursements',
      section3Content: 'Tous les achats de billets sont définitifs, sous réserve de la politique de remboursement fixée par l\'organisateur. EventNexus agit en tant qu\'intermédiaire; nous ne sommes pas responsables des annulations d\'événements mais facilitons les remboursements lorsque approuvés par l\'organisateur.',
      section4Title: '4. Contenu et comportement',
      section4Content: 'Vous ne devez pas utiliser la plateforme à des fins illégales ou non autorisées. Vous êtes seul responsable du contenu que vous téléchargez, y compris les descriptions d\'événements, images et avis. Nous nous réservons le droit de supprimer le contenu qui viole nos normes communautaires.',
    },
    privacy: {
      title: 'Politique de confidentialité',
      lastUpdated: '20 janvier 2026',
      section1Title: '1. Introduction',
      section1Content: 'Chez EventNexus, nous priorisons la sécurité des données. Cette politique de confidentialité explique comment nous collectons, utilisons et protégeons vos informations personnelles. Nous nous engageons à la transparence et à la conformité RGPD pour tous nos utilisateurs, en particulier dans l\'Union européenne.',
      section2Title: '2. Collecte de données',
      section2Content: 'Nous collectons des données minimales pour fournir des recommandations d\'événements personnalisées via notre moteur IA. Les informations collectées incluent: Adresse e-mail (requise pour la création de compte et les mises à jour d\'événements), Nom et informations de profil (facultatif), Données de localisation via GPS pour la découverte basée sur carte (avec votre permission), Statistiques d\'utilisation et informations sur l\'appareil (collectées automatiquement) et Informations de paiement traitées en toute sécurité via Stripe (nous ne stockons pas vos informations de carte de crédit).',
      section3Title: '3. Comment nous utilisons les données',
      section3Content: 'Vos données sont utilisées pour: Fournir le service de découverte basé sur carte et les recommandations d\'événements personnalisées, alimentés par notre moteur IA (Google Gemini), Traiter en toute sécurité les transactions de billets via Stripe, Envoyer des mises à jour d\'événements et des notifications sur les événements qui pourraient vous intéresser, Améliorer les performances de la plateforme grâce à l\'analytique et aux informations alimentées par l\'IA ainsi que Assurer la sécurité et la prévention de la fraude.',
      section4Title: '4. Partage de données',
      section4Content: 'Nous ne partageons vos informations de contact qu\'avec les organisateurs d\'événements pour lesquels vous avez acheté des billets. Nous ne vendons pas vos données personnelles à des tiers à des fins de marketing. Nous utilisons des prestataires de services de confiance: Google Cloud Infrastructure (hébergement et services IA), Stripe (traitement des paiements) et Supabase (base de données sécurisée avec PostgreSQL). Tous les prestataires de services sont contractuellement obligés de protéger vos données et de se conformer aux normes RGPD.',
      section5Title: '5. Infrastructure et sécurité',
      section5Content: 'EventNexus utilise Google Cloud Infrastructure pour héberger nos services et garantit une sécurité et une fiabilité de niveau entreprise. Toutes les données sont cryptées en transit et au repos. Nous mettons en œuvre des protocoles de sécurité robustes incluant des politiques Row Level Security (RLS) dans notre base de données, un traitement des paiements conforme PCI DSS Level 1 via Stripe ainsi que des audits de sécurité et une surveillance réguliers. Nous sommes entièrement conformes RGPD pour protéger nos utilisateurs de l\'UE.',
      section6Title: '6. Vos droits (RGPD)',
      section6Content: 'En vertu du RGPD, vous avez le droit d\': Accéder à vos données personnelles, Corriger les données inexactes, Supprimer vos données (droit à l\'oubli), Vous opposer au traitement des données, Portabilité des données et Retirer votre consentement à tout moment. Pour exercer ces droits, contactez-nous à support@eventnexus.eu, Temps de réponse dans les 24 heures.',
      section7Title: '7. Conservation des données',
      section7Content: 'Nous ne conservons vos données personnelles que le temps nécessaire pour fournir nos services et respecter les obligations légales. Les données de compte sont conservées tant que votre compte est actif. Les enregistrements de transactions sont conservés pendant 7 ans pour la conformité fiscale et juridique. Les données de communication marketing sont conservées jusqu\'à ce que vous vous désinscriviez.',
      section8Title: '8. Cookies et suivi',
      section8Content: 'Nous utilisons des cookies essentiels pour l\'authentification et la gestion de session. Les cookies analytiques nous aident à comprendre comment vous utilisez notre plateforme (vous pouvez vous désinscrire). Nous n\'utilisons pas de cookies publicitaires tiers. Vous pouvez gérer les paramètres des cookies dans les paramètres de votre navigateur.',
      section9Title: '9. Transferts internationaux de données',
      section9Content: 'Vos données peuvent être traitées dans des pays hors de l\'UE, y compris les États-Unis (Google Cloud, Stripe). Nous garantissons une protection adéquate par: Des clauses contractuelles types (CCT) approuvées par la Commission européenne et Des prestataires de services certifiés dans le cadre du EU-US Data Privacy Framework le cas échéant.',
      section10Title: '10. Confidentialité des enfants',
      section10Content: 'EventNexus n\'est pas destiné aux utilisateurs de moins de 16 ans. Nous ne collectons pas sciemment de données auprès d\'enfants. Si vous pensez que nous avons collecté des données d\'un enfant, contactez-nous immédiatement.',
      section11Title: '11. Modifications de cette politique',
      section11Content: 'Nous pouvons mettre à jour cette politique de confidentialité de temps à autre. Nous vous informerons des modifications substantielles par e-mail ou par avis bien visible sur notre plateforme. L\'utilisation continue après les modifications implique l\'acceptation.',
      section12Title: '12. Contactez-nous',
      section12Content: 'Pour les questions de confidentialité ou pour exercer vos droits, contactez-nous à: E-mail: support@eventnexus.eu, Temps de réponse: Dans les 24 heures, Adresse: Põltsamaa, Estonie, Entité juridique: EventNexus OÜ',
    },
