      faqTitle: 'Questions fréquemment posées',
      faq1Q: 'Comment obtenir mon billet après l\'achat?',
      faq1A: 'Une fois votre paiement confirmé, votre billet numérique avec un code QR unique est immédiatement disponible dans votre profil utilisateur sous "Mes billets". Vous recevrez également un e-mail de confirmation avec un lien vers votre billet.',
      faq2Q: 'Quelle est la politique de remboursement pour les événements?',
      faq2A: 'Les politiques de remboursement sont fixées par les organisateurs individuels. En général, vous pouvez demander un remboursement complet jusqu\'à 24 heures avant le début de l\'événement. Vérifiez la page de détails de l\'événement pour les conditions spécifiques.',
      faq3Q: 'Comment créer un événement privé, sur invitation uniquement?',
      faq3A: 'Pendant le flux de création d\'événement (Étape 3), sélectionnez "Privé / Sur invitation uniquement". Cela masquera votre événement de la carte. Vous pouvez ensuite partager un lien secret ou un code d\'accès avec vos invités.',
      faq4Q: 'Comment fonctionne la traduction IA?',
      faq4A: 'EventNexus utilise Gemini AI pour traduire automatiquement le nom et la description de votre événement dans plus de 12 langues. Cela se produit automatiquement lors de la publication et garantit une portée mondiale sans travail supplémentaire.',
      faq5Q: 'Pourquoi mon premier paiement a-t-il une période d\'attente?',
      faq5A: 'Stripe exige une période d\'attente obligatoire de 7 à 14 jours pour votre premier paiement dans le cadre de leur processus d\'atténuation des risques. Cela ne peut être contourné en aucune circonstance. Toute modification de votre méthode de paiement ou de votre calendrier pendant cette période prendra effet après la fin de la période d\'attente. Vous pouvez vérifier votre date de paiement estimée dans votre tableau de bord Stripe.',
      faq6Q: 'Quand recevrai-je mon paiement après un événement?',
      faq6A: 'Les paiements sont traités automatiquement 2 jours après la fin de votre événement. Cela permet du temps pour les demandes de remboursement et garantit des transactions sécurisées. Votre premier paiement inclut la période d\'attente Stripe de 7 à 14 jours. Ensuite, les paiements suivants suivent le calendrier standard de 2 jours de Supabase.',
