      faqTitle: 'Preguntas frecuentes',
      faq1Q: '¿Cómo obtener mi entrada después de la compra?',
      faq1A: 'Una vez confirmado tu pago, tu entrada digital con un código QR único está disponible de inmediato en tu perfil de usuario en "Mis entradas". También recibirás un correo electrónico de confirmación con un enlace a tu entrada.',
      faq2Q: '¿Cuál es la política de reembolso para eventos?',
      faq2A: 'Las políticas de reembolso las establecen los organizadores individuales. En general, puedes solicitar un reembolso completo hasta 24 horas antes del inicio del evento. Consulta la página de detalles del evento para términos específicos.',
      faq3Q: '¿Cómo crear un evento privado, solo por invitación?',
      faq3A: 'Durante el flujo de creación del evento (Paso 3), selecciona "Privado / Solo por invitación". Esto ocultará tu evento del mapa. Luego puedes compartir un enlace secreto o código de acceso con tus invitados.',
      faq4Q: '¿Cómo funciona la traducción de IA?',
      faq4A: 'EventNexus utiliza Gemini AI para traducir automáticamente el nombre y la descripción de tu evento a más de 12 idiomas. Esto ocurre automáticamente al publicar y garantiza alcance global sin trabajo adicional.',
      faq5Q: '¿Por qué mi primer pago tiene un período de espera?',
      faq5A: 'Stripe requiere un período de espera obligatorio de 7-14 días para tu primer pago como parte de su proceso de mitigación de riesgos. Esto no se puede omitir bajo ninguna circunstancia. Cualquier cambio en tu método de pago o calendario durante este tiempo entrará en vigor después de que finalice el período de espera. Puedes verificar tu fecha de pago estimada en tu panel de Stripe.',
      faq6Q: '¿Cuándo recibiré mi pago después de un evento?',
      faq6A: 'Los pagos se procesan automáticamente 2 días después de que finalice tu evento. Esto permite tiempo para solicitudes de reembolso y garantiza transacciones seguras. Tu primer pago incluye el período de espera de Stripe de 7-14 días. Después, los pagos subsiguientes siguen el calendario estándar de 2 días de Supabase.',
