    terms: {
      title: 'Warunki korzystania z usługi',
      lastUpdated: '20 stycznia 2026',
      section1Title: '1. Akceptacja warunków',
      section1Content: 'Uzyskując dostęp do lub korzystając z EventNexus, wyrażasz zgodę na niniejsze warunki korzystania z usługi. Jeśli nie zgadzasz się ze wszystkimi warunkami, nie możesz korzystać z platformy. Zastrzegamy sobie prawo do aktualizacji tych warunków w dowolnym momencie.',
      section2Title: '2. Konta użytkowników',
      section2Content: 'Musisz mieć co najmniej 18 lat, aby utworzyć konto. Jesteś odpowiedzialny za bezpieczeństwo swojego konta i hasła. EventNexus nie ponosi odpowiedzialności za straty lub szkody wynikające z nieprzestrzegania tego obowiązku bezpieczeństwa.',
      section3Title: '3. Zakupy biletów i zwroty',
      section3Content: 'Wszystkie zakupy biletów są ostateczne, z zastrzeżeniem polityki zwrotów ustalonej przez organizatora. EventNexus działa jako pośrednik; nie ponosimy odpowiedzialności za anulowanie wydarzeń, ale ułatwiamy zwroty po zatwierdzeniu przez organizatora.',
      section4Title: '4. Treści i zachowanie',
      section4Content: 'Nie wolno używać platformy do celów nielegalnych lub nieautoryzowanych. Ponosisz wyłączną odpowiedzialność za treści, które przesyłasz, w tym opisy wydarzeń, zdjęcia i recenzje. Zastrzegamy sobie prawo do usunięcia treści naruszających nasze standardy społeczności.',
    },
    privacy: {
      title: 'Polityka prywatności',
      lastUpdated: '20 stycznia 2026',
      section1Title: '1. Wprowadzenie',
      section1Content: 'W EventNexus priorytetem jest bezpieczeństwo danych. Niniejsza polityka prywatności wyjaśnia, jak gromadzimy, wykorzystujemy i chronimy Twoje dane osobowe. Jesteśmy zobowiązani do przejrzystości i zgodności z RODO dla wszystkich naszych użytkowników, szczególnie w Unii Europejskiej.',
      section2Title: '2. Gromadzenie danych',
      section2Content: 'Gromadzimy minimalne dane, aby zapewnić spersonalizowane rekomendacje wydarzeń za pośrednictwem naszego silnika AI. Gromadzone informacje obejmują: Adres e-mail (wymagany do tworzenia konta i aktualizacji wydarzeń), Imię i informacje profilowe (opcjonalnie), Dane lokalizacji za pośrednictwem GPS do odkrywania opartego na mapie (za Twoją zgodą), Statystyki użytkowania i informacje o urządzeniu (zbierane automatycznie) oraz Informacje o płatnościach przetwarzane bezpiecznie przez Stripe (nie przechowujemy informacji o karcie kredytowej).',
      section3Title: '3. Jak wykorzystujemy dane',
      section3Content: 'Twoje dane są wykorzystywane do: Zapewnienia usługi odkrywania opartej na mapie i spersonalizowanych rekomendacji wydarzeń, wspieranych przez nasz silnik AI (Google Gemini), Bezpiecznego przetwarzania transakcji biletowych przez Stripe, Wysyłania aktualizacji wydarzeń i powiadomień o wydarzeniach, które mogą Cię zainteresować, Poprawy wydajności platformy poprzez analizy i spostrzeżenia wspierane przez AI oraz Zapewnienia bezpieczeństwa i zapobiegania oszustwom.',
      section4Title: '4. Udostępnianie danych',
      section4Content: 'Udostępniamy Twoje dane kontaktowe tylko organizatorom wydarzeń, na które kupiłeś bilety. Nie sprzedajemy Twoich danych osobowych stronom trzecim w celach marketingowych. Korzystamy z zaufanych dostawców usług: Google Cloud Infrastructure (hosting i usługi AI), Stripe (przetwarzanie płatności) i Supabase (bezpieczna baza danych z PostgreSQL). Wszyscy dostawcy usług są zobowiązani umownie do ochrony Twoich danych i przestrzegania standardów RODO.',
      section5Title: '5. Infrastruktura i bezpieczeństwo',
      section5Content: 'EventNexus wykorzystuje Google Cloud Infrastructure do hostowania naszych usług i zapewnia bezpieczeństwo i niezawodność na poziomie przedsiębiorstwa. Wszystkie dane są szyfrowane podczas przesyłania i w spoczynku. Wdrażamy solidne protokoły bezpieczeństwa, w tym polityki Row Level Security (RLS) w naszej bazie danych, przetwarzanie płatności zgodne z PCI DSS Level 1 przez Stripe oraz regularne audyty bezpieczeństwa i monitorowanie. Jesteśmy w pełni zgodni z RODO, aby chronić naszych użytkowników z UE.',
      section6Title: '6. Twoje prawa (RODO)',
      section6Content: 'Zgodnie z RODO masz prawo do: Dostępu do swoich danych osobowych, Korekty niedokładnych danych, Usunięcia swoich danych (prawo do bycia zapomnianym), Sprzeciwu wobec przetwarzania danych, Przenoszenia danych i Wycofania zgody w dowolnym momencie. Aby skorzystać z tych praw, skontaktuj się z nami pod adresem support@eventnexus.eu, Czas odpowiedzi w ciągu 24 godzin.',
      section7Title: '7. Przechowywanie danych',
      section7Content: 'Przechowujemy Twoje dane osobowe tylko tak długo, jak jest to konieczne do świadczenia naszych usług i spełnienia zobowiązań prawnych. Dane konta są przechowywane, dopóki Twoje konto jest aktywne. Rejestry transakcji są przechowywane przez 7 lat w celach podatkowych i zgodności prawnej. Dane komunikacji marketingowej są przechowywane do czasu rezygnacji.',
      section8Title: '8. Pliki cookie i śledzenie',
      section8Content: 'Używamy niezbędnych plików cookie do uwierzytelniania i zarządzania sesją. Pliki cookie analityczne pomagają nam zrozumieć, jak korzystasz z naszej platformy (możesz zrezygnować). Nie używamy plików cookie reklamowych stron trzecich. Możesz zarządzać ustawieniami plików cookie w ustawieniach przeglądarki.',
      section9Title: '9. Międzynarodowe transfery danych',
      section9Content: 'Twoje dane mogą być przetwarzane w krajach poza UE, w tym w Stanach Zjednoczonych (Google Cloud, Stripe). Zapewniamy odpowiednią ochronę poprzez: Standardowe klauzule umowne (SCC) zatwierdzone przez Komisję Europejską oraz Dostawców usług certyfikowanych w ramach EU-US Data Privacy Framework, gdzie ma to zastosowanie.',
      section10Title: '10. Prywatność dzieci',
      section10Content: 'EventNexus nie jest przeznaczony dla użytkowników poniżej 16 roku życia. Nie gromadzimy świadomie danych od dzieci. Jeśli uważasz, że zebraliśmy dane od dziecka, skontaktuj się z nami natychmiast.',
      section11Title: '11. Zmiany w tej polityce',
      section11Content: 'Możemy od czasu do czasu aktualizować tę politykę prywatności. Powiadomimy Cię o istotnych zmianach za pośrednictwem poczty elektronicznej lub poprzez widoczne powiadomienie na naszej platformie. Kontynuowanie korzystania po zmianach oznacza akceptację.',
      section12Title: '12. Skontaktuj się z nami',
      section12Content: 'W sprawach prywatności lub w celu skorzystania z przysługujących Ci praw, skontaktuj się z nami pod adresem: E-mail: support@eventnexus.eu, Czas odpowiedzi: W ciągu 24 godzin, Adres: Põltsamaa, Estonia, Podmiot prawny: EventNexus OÜ',
    },
